// game.js – Canvas Escape (endless runner)
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth || 800);
  const H = (canvas.height = canvas.offsetHeight || 600);

  // player (triangle) state
  const player = {
    x: W / 2,
    y: H - 30,
    size: 20,
    vy: 0,
    onGround: true,
  };

  const GRAVITY = 0.6;
  const JUMP_SPEED = -12;

  // obstacles – simple rectangles
  const obstacles = [];
  const OBSTACLE_W = 40;
  const OBSTACLE_H = 20;
  const OBSTACLE_SPEED = 3;
  let obstacleTimer = 0;
  const OBSTACLE_INTERVAL = 90; // frames

  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function reset() {
    player.x = W / 2;
    player.y = H - 30;
    player.vy = 0;
    player.onGround = true;
    obstacles.length = 0;
    obstacleTimer = 0;
    gameOver = false;
  }

  function update() {
    if (gameOver) return;
    // player horizontal movement
    if (keys.ArrowLeft) player.x -= 5;
    if (keys.ArrowRight) player.x += 5;
    // keep within bounds
    player.x = Math.max(player.size, Math.min(W - player.size, player.x));

    // jump
    if (keys.ArrowUp && player.onGround) {
      player.vy = JUMP_SPEED;
      player.onGround = false;
    }
    // gravity
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y >= H - 30) {
      player.y = H - 30;
      player.vy = 0;
      player.onGround = true;
    }

    // obstacles generation
    if (obstacleTimer-- <= 0) {
      obstacleTimer = OBSTACLE_INTERVAL;
      const x = Math.random() * (W - OBSTACLE_W);
      obstacles.push({ x, y: -OBSTACLE_H, w: OBSTACLE_W, h: OBSTACLE_H });
    }
    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.y += OBSTACLE_SPEED;
      // remove off‑screen
      if (o.y > H) obstacles.splice(i, 1);
    }

    // collision detection (simple AABB against player bounding box)
    const pBox = {
      left: player.x - player.size,
      right: player.x + player.size,
      top: player.y - player.size,
      bottom: player.y + player.size,
    };
    for (const o of obstacles) {
      if (
        pBox.right > o.x &&
        pBox.left < o.x + o.w &&
        pBox.bottom > o.y &&
        pBox.top < o.y + o.h
      ) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // player – triangle pointing up
    ctx.fillStyle = '#0b79d0';
    ctx.beginPath();
    ctx.moveTo(player.x, player.y - player.size);
    ctx.lineTo(player.x - player.size, player.y + player.size);
    ctx.lineTo(player.x + player.size, player.y + player.size);
    ctx.closePath();
    ctx.fill();
    // obstacles
    ctx.fillStyle = '#c33';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over – Press R to Restart', W / 2, H / 2);
    }
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  // restart on R key when game over
  window.addEventListener('keydown', e => {
    if (gameOver && e.key === 'r') reset();
  });

  reset();
  loop();
})();
